{
  "quantity": {
    "description": "Change in own-team expected single-game scoring margin from adopting the strategy",
    "units": "points",
    "support": "unbounded real; positive favors own team"
  },
  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Model-driven fourth downs and 2-point tries",
      "recommendation": "Use an in-game EP/WP card as the default: go for most fourth-and-1/2 around midfield and in plus territory, be willing to go for fourth-and-goal rather than take short field goals, and follow model-based 2-point choices instead of score-chart folklore. I can override only for concrete information such as injury, weather, or a known protection issue.",
      "rationale": "Public win-probability and expected-points models repeatedly price possession and touchdown equity above conservative punts and short kicks; converting even a few high-leverage decisions raises scoring margin and reduces reliance on close-game variance.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.37,
          "interval_95_low": -0.17,
          "interval_95_high": 0.91,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The public evidence points positive, but implementation mistakes and matchup overrides can cut both ways. A normal prior is adequate for roughly symmetric, non-heavy uncertainty."
        },
        "parameters": {
          "mu": 0.37,
          "sigma": 0.2755102041,
          "conversion_note": "mu = most_plausible = 0.37. sigma = (0.91 - (-0.17))/(2*1.96) = 1.08/3.92 = 0.2755. This is a subjective matching prior, not a precise measured edge."
        },
        "consistency_check": "0.37 lies inside [-0.17, 0.91]. The normal family has unbounded real support, so negative and positive signed effects are both allowed."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "Pass-biased early-down offense",
      "recommendation": "Shift neutral early downs toward efficient passes: play-action, RPO/glance, motion/formation leverage, and quick-game answers rather than run-run-pass. Keep enough called runs for constraint, but make the pass menu the first-down default unless matchup or weather clearly says otherwise.",
      "rationale": "Public EPA research consistently finds that early-down passing and play-action create more value than conventional run rates, improving the chance of staying ahead of the sticks and finishing drives with touchdowns.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.23,
          "interval_95_low": -0.49,
          "interval_95_high": 0.95,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The mean case is positive, but the realized effect depends heavily on quarterback accuracy, protection, and opponent adaptation. A Student-t prior gives more mass to unexpectedly large positive or negative effects."
        },
        "parameters": {
          "nu": 7,
          "mu": 0.23,
          "sigma": 0.3045,
          "conversion_note": "nu = 7 and t_{0.975,7} = 2.3646. mu = 0.23. sigma = (0.95 - (-0.49))/(2*2.3646) = 1.44/4.7292 = 0.3045; sigma is the t scale, not the SD. This is a subjective matching prior, not a precise measured edge."
        },
        "consistency_check": "0.23 lies inside [-0.49, 0.95]. The Student-t family has unbounded real support, so negative and positive signed effects are both allowed."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Pass-first defensive resource allocation",
      "recommendation": "Treat defending the pass as the default resource allocation: more nickel/dime, split-safety shells, and light boxes on neutral downs, with four-man rush or simulated pressure rather than run-first front structures. Force offenses to prove they can patiently win with runs before I spin down a safety.",
      "rationale": "Public EPA work shows successful passes and explosive passes dominate scoring; accepting some rush efficiency can still improve win probability if it lowers explosive pass rate and third-down stress.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.14,
          "interval_95_low": -0.58,
          "interval_95_high": 0.86,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The analytics case is real but less direct than fourth-down math, and personnel fit can make the tradeoff backfire. A Student-t prior reflects that this is a weaker, matchup-sensitive analytics pick."
        },
        "parameters": {
          "nu": 7,
          "mu": 0.14,
          "sigma": 0.3045,
          "conversion_note": "nu = 7 and t_{0.975,7} = 2.3646. mu = 0.14. sigma = (0.86 - (-0.58))/(2*2.3646) = 1.44/4.7292 = 0.3045; sigma is the t scale, not the SD. This is a subjective matching prior, not a precise measured edge."
        },
        "consistency_check": "0.14 lies inside [-0.58, 0.86]. The Student-t family has unbounded real support, so negative and positive signed effects are both allowed."
      }
    },
    {
      "bucket": "intuition",
      "type": "game_management",
      "title": "Pre-delegated game-management desk",
      "recommendation": "Install a pre-delegated game-management desk: one staffer owns clock, timeout, and challenge math, communicates only pre-agreed options, and has authority to stop me from a heat-of-moment timeout or challenge. This is intuition because public analytics grades the decisions themselves, not whether this sideline workflow and authority structure improves those decisions under stress.",
      "rationale": "The edge is avoiding one or two high-leverage process errors per month without distracting play-callers; even rare prevented mistakes can swing win probability.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.06,
          "interval_95_low": -0.2,
          "interval_95_high": 0.32,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The effect should usually be small because the relevant situations are infrequent. A normal prior with light tails matches a process improvement that can also create communication clutter if done poorly."
        },
        "parameters": {
          "mu": 0.06,
          "sigma": 0.1326530612,
          "conversion_note": "mu = most_plausible = 0.06. sigma = (0.32 - (-0.20))/(2*1.96) = 0.52/3.92 = 0.1327. This is a subjective matching prior, not a precise measured edge."
        },
        "consistency_check": "0.06 lies inside [-0.20, 0.32]. The normal family has unbounded real support, so negative and positive signed effects are both allowed."
      }
    },
    {
      "bucket": "intuition",
      "type": "offensive",
      "title": "Real package for a changeup QB",
      "recommendation": "Carry a real weekly package for a changeup quarterback or position player who can threaten QB run plus a credible pass on short yardage, low red zone, and select sudden-change drives; practice it enough that it is not a gadget. This is intuition because public evidence on true QB platoon packages is sparse and heavily player-specific, not a settled leaguewide EPA rule.",
      "rationale": "It can steal high-leverage first downs and red-zone touchdowns by forcing opponents to prepare for a structurally different run fit, but the prior stays modest because rhythm and roster-cost downsides are real.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.08,
          "interval_95_low": -0.31,
          "interval_95_high": 0.78,
          "shape": "right_skewed",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "Most teams will get little more than a small situational edge, but the upside tail is longer if the package solves a real short-yardage or red-zone weakness. A skew_normal keeps signed support while allowing asymmetric upside."
        },
        "parameters": {
          "xi": -0.1283,
          "omega": 0.4075,
          "alpha": 2.2,
          "conversion_note": "alpha = +2.2 for moderate right skew. I fit scipy.stats.skewnorm numerically to mode about 0.08 and central 95% about [-0.31, 0.78], yielding xi = -0.1283 and omega = 0.4075; standardized landmarks are approximately q0.025 = -0.45, mode = 0.52, q0.975 = 2.23. This is a subjective matching prior, not a precise measured edge."
        },
        "consistency_check": "0.08 lies inside [-0.31, 0.78]. The skew_normal family has unbounded real support, so negative and positive signed effects are both allowed; the mode and interval match are numerical approximations."
      }
    },
    {
      "bucket": "intuition",
      "type": "defensive",
      "title": "Opponent-specific surprise defensive package",
      "recommendation": "Each week, reserve a small defensive call sheet for an opponent-specific surprise: one coverage inversion, one creeper or simulated pressure, and one red-zone bracket that are not on our recent tape but are simple enough to execute. This is intuition because public analytics can measure blitz and coverage results in aggregate, but not my opponent-specific deception package, practice tradeoff, or game-theory timing.",
      "rationale": "The goal is not to live in exotic calls; it is to buy a hesitation, a throw into a disguised window, or a drive-killing negative play while limiting exposure to busts.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.04,
          "interval_95_low": -0.48,
          "interval_95_high": 0.56,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The most likely effect is near zero, but the tails are real: a surprise can create a turnover, while a bust can create an explosive touchdown. A low-degree Student-t captures that high-variance, weakly informed prior."
        },
        "parameters": {
          "nu": 4,
          "mu": 0.04,
          "sigma": 0.1873,
          "conversion_note": "nu = 4 and t_{0.975,4} = 2.7764. mu = 0.04. sigma = (0.56 - (-0.48))/(2*2.7764) = 1.04/5.5528 = 0.1873; sigma is the t scale, not the SD. This is a subjective matching prior, not a precise measured edge."
        },
        "consistency_check": "0.04 lies inside [-0.48, 0.56]. The Student-t family has unbounded real support, so negative and positive signed effects are both allowed."
      }
    }
  ],
  "plot_script": "import numpy as np\nfrom scipy.stats import norm, t, skewnorm\nimport matplotlib.pyplot as plt\n\nstrategies = [\n    {'title': 'Model-driven fourth downs and 2-point tries', 'family': 'normal', 'params': {'mu': 0.37, 'sigma': 0.2755102041}, 'mpv': 0.37},\n    {'title': 'Pass-biased early-down offense', 'family': 'student_t', 'params': {'nu': 7, 'mu': 0.23, 'sigma': 0.3045}, 'mpv': 0.23},\n    {'title': 'Pass-first defensive resource allocation', 'family': 'student_t', 'params': {'nu': 7, 'mu': 0.14, 'sigma': 0.3045}, 'mpv': 0.14},\n    {'title': 'Pre-delegated game-management desk', 'family': 'normal', 'params': {'mu': 0.06, 'sigma': 0.1326530612}, 'mpv': 0.06},\n    {'title': 'Real package for a changeup QB', 'family': 'skew_normal', 'params': {'xi': -0.1283, 'omega': 0.4075, 'alpha': 2.2}, 'mpv': 0.08},\n    {'title': 'Opponent-specific surprise defensive package', 'family': 'student_t', 'params': {'nu': 4, 'mu': 0.04, 'sigma': 0.1873}, 'mpv': 0.04},\n]\n\ndef make_dist(spec):\n    family = spec['family']\n    p = spec['params']\n    if family == 'normal':\n        return norm(loc=p['mu'], scale=p['sigma'])\n    if family == 'student_t':\n        return t(df=p['nu'], loc=p['mu'], scale=p['sigma'])\n    if family == 'skew_normal':\n        return skewnorm(a=p['alpha'], loc=p['xi'], scale=p['omega'])\n    raise ValueError('Unknown family: ' + str(family))\n\nfor s in strategies:\n    print(s['title'] + ': ' + s['family'] + ' ' + str(s['params']))\n\nfig, axes = plt.subplots(3, 2, figsize=(13, 10), constrained_layout=True)\naxes = np.ravel(axes)\nfor ax, spec in zip(axes, strategies):\n    dist = make_dist(spec)\n    q_lo = dist.ppf(0.025)\n    q_hi = dist.ppf(0.975)\n    x_lo = dist.ppf(0.001)\n    x_hi = dist.ppf(0.999)\n    span = x_hi - x_lo\n    x = np.linspace(x_lo - 0.05 * span, x_hi + 0.05 * span, 800)\n    y = dist.pdf(x)\n    ax.plot(x, y, color='tab:blue', linewidth=2)\n    mask = (x >= q_lo) & (x <= q_hi)\n    ax.fill_between(x[mask], 0, y[mask], color='tab:blue', alpha=0.25, label='central 95%')\n    ax.axvline(spec['mpv'], color='black', linestyle='--', linewidth=1.4, label='most plausible')\n    ax.axvline(q_lo, color='tab:blue', linestyle=':', linewidth=1.0)\n    ax.axvline(q_hi, color='tab:blue', linestyle=':', linewidth=1.0)\n    ax.set_title(spec['title'])\n    ax.set_xlabel('Change in own scoring margin (points)')\n    ax.set_ylabel('Density')\n    ax.legend(loc='best', fontsize=8)\n\nplt.show()\n"
}
